"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  currencyAffix,
  currencyFractionDigits,
  currencyName,
  formatForEditing,
  getSeparators,
  normalizeDigits,
  padFraction,
  parseMoney,
  toEditable,
} from "@/registry/tellerline/lib/money"

export type MoneyInputChange = {
  /** Canonical decimal string, for example "-1234.5", or null when empty. Never a JavaScript number. */
  value: string | null
  /** Why the last input was refused, if it was. */
  rejected?: "invalid" | "too-many-decimals" | "negative-not-allowed"
}

export type MoneyInputProps = Omit<
  React.ComponentProps<"input">,
  "value" | "defaultValue" | "onChange" | "type" | "inputMode"
> & {
  /** ISO 4217 currency code. */
  currency: string
  /** Locale for separators and digits. Defaults to "en-US". */
  locale?: string
  /** Controlled value as a canonical decimal string. */
  value?: string | null
  defaultValue?: string | null
  onValueChange?: (value: string | null, change: MoneyInputChange) => void
  /** Overrides the fraction digits the currency allows. */
  fractionDigits?: number
  /** Accepts a minus sign or an amount in parentheses. Off by default. */
  allowNegative?: boolean
  /** Lets people type "1.5k" or "2m". Off by default. */
  allowShortcuts?: boolean
  /** How the currency is shown next to the number. */
  currencyDisplay?: "symbol" | "narrowSymbol" | "code" | "none"
  /** Classes for the wrapper that holds the input and the currency. */
  containerClassName?: string
}

const isSignificant = (ch: string, decimal: string) => /\d/.test(normalizeDigits(ch)) || ch === decimal || ch === "-"

/** How many digits, decimal points and minus signs come before `pos`: the caret's position in terms that survive reformatting. */
function significantBefore(text: string, pos: number, decimal: string) {
  let n = 0
  for (let i = 0; i < pos && i < text.length; i++) if (isSignificant(text[i], decimal)) n++
  return n
}

function positionAfter(text: string, count: number, decimal: string) {
  if (count <= 0) return 0
  let n = 0
  for (let i = 0; i < text.length; i++) {
    if (isSignificant(text[i], decimal)) n++
    if (n === count) return i + 1
  }
  return text.length
}

/**
 * A text input for money. It groups digits as you type, keeps the caret where you left it, refuses more fraction digits
 * than the currency has instead of rounding, accepts pasted amounts in any common format and "1.5k" shortcuts,
 * and hands back a decimal string you can store or send without floating point error.
 */
export function MoneyInput({
  currency,
  locale = "en-US",
  value,
  defaultValue = null,
  onValueChange,
  fractionDigits,
  allowNegative = false,
  allowShortcuts = false,
  currencyDisplay = "symbol",
  className,
  containerClassName,
  onBlur,
  onFocus,
  onKeyDown,
  onPaste,
  disabled,
  "aria-describedby": describedBy,
  ...props
}: MoneyInputProps) {
  const digits = fractionDigits ?? currencyFractionDigits(currency, locale)
  const { decimal } = getSeparators(locale)
  const options = { currency, locale, fractionDigits: digits, allowNegative, allowShortcuts }

  const controlled = value !== undefined
  const [inner, setInner] = React.useState<string | null>(defaultValue)
  const current = controlled ? value : inner

  const display = (v: string | null, editing: boolean) =>
    v === null ? "" : formatForEditing(editing ? v : padFraction(v, digits), locale)

  const inputRef = React.useRef<HTMLInputElement>(null)
  const [text, setText] = React.useState(() => display(current, false))
  const focused = React.useRef(false)
  const composing = React.useRef(false)
  const caret = React.useRef<number | null>(null)
  // Re-renders after a refused keystroke, so React restores the text and the caret goes back where it was.
  const [, rerender] = React.useReducer((n: number) => n + 1, 0)
  const lastEmitted = React.useRef(current)

  // A new value from outside replaces what is shown, unless it is the value this input just reported.
  React.useEffect(() => {
    if (current !== lastEmitted.current) {
      lastEmitted.current = current
      setText(display(current, focused.current))
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [current])

  React.useLayoutEffect(() => {
    if (caret.current !== null && inputRef.current && document.activeElement === inputRef.current) {
      inputRef.current.setSelectionRange(caret.current, caret.current)
      caret.current = null
    }
  })

  const emit = (next: string | null, change: MoneyInputChange) => {
    lastEmitted.current = next
    if (!controlled) setInner(next)
    onValueChange?.(next, change)
  }

  const reject = (reason: NonNullable<MoneyInputChange["rejected"]>) => onValueChange?.(current, { value: current, rejected: reason })

  const handleChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const el = event.target
    if (composing.current) {
      setText(el.value)
      return
    }
    const raw = toEditable(el.value, locale)
    if (raw === null || (raw.startsWith("-") && !allowNegative)) {
      reject(raw === null ? "invalid" : "negative-not-allowed")
      caret.current = Math.max(0, (el.selectionStart ?? 1) - 1)
      rerender()
      return
    }
    const fraction = raw.split(".")[1]
    if (fraction !== undefined && fraction.length > digits) {
      reject("too-many-decimals")
      caret.current = Math.max(0, (el.selectionStart ?? 1) - 1)
      rerender()
      return
    }
    if (digits === 0 && raw.includes(".")) {
      reject("too-many-decimals")
      caret.current = Math.max(0, (el.selectionStart ?? 1) - 1)
      rerender()
      return
    }
    const formatted = raw === "" || raw === "-" ? raw : formatForEditing(raw, locale)
    caret.current = positionAfter(formatted, significantBefore(el.value, el.selectionStart ?? el.value.length, decimal), decimal)
    setText(formatted)
    const parsed = raw === "" || raw === "-" || raw === "." ? { ok: true as const, value: null } : parseMoney(raw, options)
    if (parsed.ok && parsed.value !== current) emit(parsed.value, { value: parsed.value })
  }

  // Backspace right after a group separator deletes the digit before it, instead of removing the separator only to see it come back.
  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    onKeyDown?.(event)
    if (event.defaultPrevented) return
    const el = event.currentTarget
    const start = el.selectionStart ?? 0
    if (start !== el.selectionEnd) return
    if (event.key === "Backspace" && start > 0 && !isSignificant(el.value[start - 1], decimal)) {
      el.setSelectionRange(start - 1, start - 1)
    } else if (event.key === "Delete" && start < el.value.length && !isSignificant(el.value[start], decimal)) {
      el.setSelectionRange(start + 1, start + 1)
    }
  }

  // A paste is read as a whole amount ("$1,234.50", "(12.00)", "1.5k"), not character by character.
  const handlePaste = (event: React.ClipboardEvent<HTMLInputElement>) => {
    onPaste?.(event)
    if (event.defaultPrevented) return
    const el = event.currentTarget
    const pasted = event.clipboardData.getData("text")
    const whole = el.selectionStart === 0 && el.selectionEnd === el.value.length
    if (!whole && el.value !== "") return
    event.preventDefault()
    const parsed = parseMoney(pasted, options)
    if (!parsed.ok) return reject(parsed.reason)
    const next = display(parsed.value, true)
    caret.current = next.length
    setText(next)
    emit(parsed.value, { value: parsed.value })
  }

  const handleBlur = (event: React.FocusEvent<HTMLInputElement>) => {
    focused.current = false
    setText(display(current, false))
    onBlur?.(event)
  }

  const handleFocus = (event: React.FocusEvent<HTMLInputElement>) => {
    focused.current = true
    onFocus?.(event)
  }

  const affix = currencyDisplay === "none" ? null : currencyAffix({ currency, locale, display: currencyDisplay })
  const nameId = React.useId()

  return (
    <div
      data-slot="money-input"
      data-disabled={disabled || undefined}
      className={cn(
        "border-input dark:bg-input/30 flex h-9 w-full min-w-0 items-center gap-2 rounded-md border bg-transparent px-3 shadow-xs transition-[color,box-shadow]",
        "focus-within:border-ring focus-within:ring-ring/50 focus-within:ring-[3px]",
        "has-[input[aria-invalid=true]]:border-destructive has-[input[aria-invalid=true]]:ring-destructive/20",
        "data-[disabled]:pointer-events-none data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        affix?.position === "suffix" && "flex-row-reverse",
        containerClassName,
      )}
    >
      {affix && (
        <span aria-hidden className="text-muted-foreground shrink-0 text-sm tabular-nums select-none">
          {affix.symbol}
        </span>
      )}
      <input
        ref={inputRef}
        type="text"
        inputMode="decimal"
        autoComplete="off"
        spellCheck={false}
        dir="ltr"
        disabled={disabled}
        aria-describedby={describedBy ? `${nameId} ${describedBy}` : nameId}
        {...props}
        value={text}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onPaste={handlePaste}
        onBlur={handleBlur}
        onFocus={handleFocus}
        onCompositionStart={() => (composing.current = true)}
        onCompositionEnd={(event) => {
          composing.current = false
          handleChange(event as unknown as React.ChangeEvent<HTMLInputElement>)
        }}
        className={cn(
          "placeholder:text-muted-foreground min-w-0 flex-1 bg-transparent text-base tabular-nums outline-none md:text-sm",
          "text-right",
          className,
        )}
      />
      {/* Hidden, so it never joins the name of a <label> wrapped around the input, but still read as the description. */}
      <span id={nameId} hidden>
        {currencyName(currency, locale)}
      </span>
    </div>
  )
}

/**
 * Decimal-safe money helpers. Amounts are canonical decimal strings ("-1234.5"), never JavaScript
 * numbers, so nothing is ever rounded by floating point. Minor units are BigInt.
 */

export type MoneyOptions = {
  /** ISO 4217 code, for example "USD", "EUR", "JPY". */
  currency: string
  /** BCP 47 locale used for separators and digits. Defaults to "en-US". */
  locale?: string
  /** Overrides the number of fraction digits the currency allows. */
  fractionDigits?: number
}

export type ParseResult =
  | { ok: true; value: string | null }
  | { ok: false; reason: "invalid" | "too-many-decimals" | "negative-not-allowed" }

// Bidi marks and invisible characters that Intl puts around numbers in some locales.
const INVISIBLE = /[‎‏؜⁦-⁩‪-‮]/g
const SPACES = /[\s   ]/g
const MINUS = /^[-−‒–]/
const SHORTCUTS: Record<string, number> = { k: 3, m: 6, b: 9 }

/** Turns Arabic-Indic and Extended Arabic-Indic digits into ASCII and drops invisible bidi marks. */
export function normalizeDigits(input: string): string {
  return input
    .replace(INVISIBLE, "")
    .replace(/[٠-٩]/g, (d) => String(d.charCodeAt(0) - 0x0660))
    .replace(/[۰-۹]/g, (d) => String(d.charCodeAt(0) - 0x06f0))
}

const separatorCache = new Map<string, { group: string; decimal: string }>()

/** The group and decimal separators a locale uses, read from Intl rather than guessed. */
export function getSeparators(locale = "en-US") {
  let seps = separatorCache.get(locale)
  if (!seps) {
    const parts = new Intl.NumberFormat(locale).formatToParts(1234567.5)
    seps = {
      group: parts.find((p) => p.type === "group")?.value ?? ",",
      decimal: parts.find((p) => p.type === "decimal")?.value ?? ".",
    }
    separatorCache.set(locale, seps)
  }
  return seps
}

/** Fraction digits for a currency as the runtime's CLDR data defines them (JPY 0, USD 2, KWD 3). */
export function currencyFractionDigits(currency: string, locale = "en-US"): number {
  return new Intl.NumberFormat(locale, { style: "currency", currency }).resolvedOptions().maximumFractionDigits ?? 2
}

function digitsFor(opts: MoneyOptions) {
  return opts.fractionDigits ?? currencyFractionDigits(opts.currency, opts.locale)
}

/** Moves the decimal point of a canonical decimal string `places` to the right. */
function shiftDecimal(value: string, places: number): string {
  const negative = value.startsWith("-")
  const [int, frac = ""] = value.replace("-", "").split(".")
  const digits = int + frac.padEnd(places, "0")
  const point = int.length + places
  return canonical(negative, digits.slice(0, point), digits.slice(point))
}

function canonical(negative: boolean, int: string, frac: string): string {
  const i = int.replace(/^0+(?=\d)/, "") || "0"
  const f = frac.replace(/0+$/, "")
  const body = f ? `${i}.${f}` : i
  return negative && /[1-9]/.test(body) ? `-${body}` : body
}

/**
 * Parses what a person typed or pasted into a canonical decimal string.
 * Accepts the locale's separators, "." as the decimal point when the locale does not use it for grouping,
 * accounting negatives "(12.00)", a leading minus, currency symbols and codes, and k/m/b shortcuts ("1.5k").
 * It never rounds: more fraction digits than the currency allows is an error, not a silent change.
 */
export function parseMoney(
  input: string,
  opts: MoneyOptions & { allowNegative?: boolean; allowShortcuts?: boolean },
): ParseResult {
  const locale = opts.locale ?? "en-US"
  const { group, decimal } = getSeparators(locale)
  let s = normalizeDigits(input).replace(SPACES, "").trim()
  if (s === "") return { ok: true, value: null }

  let negative = false
  if (/^\(.*\)$/.test(s)) {
    negative = true
    s = s.slice(1, -1)
  }
  // Currency symbols and codes may sit on either side of the number, and a minus may sit outside a symbol ("-$5").
  s = s.replace(/^[^\d\-−‒–.,٫٬']+/u, "")
  if (MINUS.test(s)) {
    negative = !negative
    s = s.slice(1)
  }
  s = s.replace(/^[^\d.,٫٬']+/u, "")

  let shift = 0
  // Only directly after a digit, so a currency code such as "DKK" or "BAM" is not read as a shortcut.
  const shortcut = /\d([kmb])$/i.exec(s)
  if (shortcut && opts.allowShortcuts !== false) {
    shift = SHORTCUTS[shortcut[1].toLowerCase()]
    s = s.slice(0, -1)
  } else {
    s = s.replace(/[^\d.,٫٬']+$/u, "")
  }

  const decimals = new Set([decimal, "٫"])
  if (group !== ".") decimals.add(".")
  const groups = new Set([group, "٬", "'", "’"])
  if (group === " " || group === " ") groups.add(" ")
  if (decimal !== ",") groups.add(",")

  let int = ""
  let frac = ""
  let seenDecimal = false
  for (const ch of s) {
    if (ch >= "0" && ch <= "9") {
      if (seenDecimal) frac += ch
      else int += ch
    } else if (decimals.has(ch) && !seenDecimal) {
      seenDecimal = true
    } else if (groups.has(ch) && !seenDecimal) {
      continue
    } else {
      return { ok: false, reason: "invalid" }
    }
  }
  if (int === "" && frac === "") return seenDecimal ? { ok: true, value: "0" } : { ok: false, reason: "invalid" }

  let value = canonical(negative, int, frac)
  if (shift) value = shiftDecimal(value, shift)
  if (value.startsWith("-") && opts.allowNegative === false) return { ok: false, reason: "negative-not-allowed" }
  const fracLen = value.split(".")[1]?.length ?? 0
  if (fracLen > digitsFor(opts)) return { ok: false, reason: "too-many-decimals" }
  return { ok: true, value }
}

/** "12.3" with 2 digits becomes 1230n. Throws if the value has more fraction digits than allowed. */
export function toMinorUnits(value: string, fractionDigits: number): bigint {
  if (!/^-?\d+(\.\d+)?$/.test(value)) throw new TypeError(`Not a decimal string: ${value}`)
  const negative = value.startsWith("-")
  const [int, frac = ""] = value.replace("-", "").split(".")
  if (frac.length > fractionDigits) throw new RangeError(`${value} has more than ${fractionDigits} fraction digits`)
  const minor = BigInt(int + frac.padEnd(fractionDigits, "0"))
  return negative ? -minor : minor
}

/** 1230n with 2 digits becomes "12.3". */
export function fromMinorUnits(minor: bigint, fractionDigits: number): string {
  const negative = minor < BigInt(0)
  const digits = (negative ? -minor : minor).toString().padStart(fractionDigits + 1, "0")
  const point = digits.length - fractionDigits
  return canonical(negative, digits.slice(0, point), digits.slice(point))
}

/** Pads the fraction to the currency's digits without rounding: "12.5" USD becomes "12.50". */
export function padFraction(value: string, fractionDigits: number): string {
  if (fractionDigits === 0) return value
  const [int, frac = ""] = value.split(".")
  return `${int}.${frac.padEnd(fractionDigits, "0")}`
}

/**
 * Formats a canonical decimal string as money. Intl formats the string exactly (no Number conversion),
 * so amounts beyond 2^53 keep every digit.
 */
export function formatMoney(
  value: string,
  opts: MoneyOptions & { display?: "symbol" | "narrowSymbol" | "code" | "name" | "none" },
): string {
  const fractionDigits = digitsFor(opts)
  const display = opts.display ?? "symbol"
  const nf = new Intl.NumberFormat(opts.locale ?? "en-US", {
    ...(display === "none" ? {} : { style: "currency", currency: opts.currency, currencyDisplay: display }),
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: Math.max(fractionDigits, value.split(".")[1]?.length ?? 0),
  })
  return nf.format(value as unknown as number)
}

/** Where the currency symbol goes for a locale, and the symbol itself. */
export function currencyAffix(opts: MoneyOptions & { display?: "symbol" | "narrowSymbol" | "code" }) {
  const parts = new Intl.NumberFormat(opts.locale ?? "en-US", {
    style: "currency",
    currency: opts.currency,
    currencyDisplay: opts.display ?? "symbol",
  }).formatToParts(1)
  const at = parts.findIndex((p) => p.type === "currency")
  const integerAt = parts.findIndex((p) => p.type === "integer")
  return { symbol: parts[at]?.value.replace(INVISIBLE, "") ?? opts.currency, position: at < integerAt ? "prefix" : "suffix" } as const
}

/** The full currency name, for screen readers: "US dollars". */
export function currencyName(currency: string, locale = "en-US"): string {
  try {
    return new Intl.DisplayNames([locale], { type: "currency" }).of(currency) ?? currency
  } catch {
    return currency
  }
}

const digitCache = new Map<string, string[]>()
function localeDigits(locale: string): string[] {
  let digits = digitCache.get(locale)
  if (!digits) {
    const nf = new Intl.NumberFormat(locale, { useGrouping: false })
    digits = Array.from({ length: 10 }, (_, d) => nf.format(d).replace(INVISIBLE, ""))
    digitCache.set(locale, digits)
  }
  return digits
}

/**
 * The text shown while someone edits: the integer part grouped for the locale, the fraction exactly as typed,
 * including a trailing decimal point or zeros, so typing "12." or "12.50" is never fought.
 */
export function formatForEditing(raw: string, locale = "en-US"): string {
  const { group, decimal } = getSeparators(locale)
  const negative = raw.startsWith("-")
  const [int = "", frac] = raw.replace("-", "").split(".")
  const digits = localeDigits(locale)
  const local = (s: string) => s.replace(/\d/g, (d) => digits[Number(d)])
  let grouped = ""
  for (let i = 0; i < int.length; i++) {
    if (i > 0 && (int.length - i) % 3 === 0) grouped += group
    grouped += int[i]
  }
  return `${negative ? "-" : ""}${local(grouped)}${frac === undefined ? "" : decimal + local(frac)}`
}

/**
 * Reduces what is in the input to a raw editable string: ASCII digits, at most one ".", an optional leading "-".
 * Unlike parseMoney it keeps a trailing "." and trailing zeros, because the person is still typing.
 */
export function toEditable(text: string, locale = "en-US"): string | null {
  const { group, decimal } = getSeparators(locale)
  const s = normalizeDigits(text).replace(SPACES, "")
  let out = ""
  let seenDecimal = false
  for (const [i, ch] of [...s].entries()) {
    if (ch >= "0" && ch <= "9") out += ch
    else if ((ch === decimal || ch === "٫" || (ch === "." && group !== ".")) && !seenDecimal) {
      seenDecimal = true
      out += "."
    } else if (i === 0 && MINUS.test(ch)) out += "-"
    else if (ch === group || ch === "," || ch === "'" || ch === "٬" || ch === ".") continue
    else return null
  }
  return out
}
